import React from "react";
import { Form } from "antd";
export default function CustomFormItem({ error, label, touched, children, className }) {
  const FormItem = Form.Item;
  return (
    <FormItem

      className={className}
      help={touched && error ? error : ""}
      validateStatus={touched && error ? "error" : undefined}
      label={label}
    >
      {children}
    </FormItem>
  );
}
